def isValid(word: str) -> bool:
    if len(word) < 3:
        return False

    vowels = set("aeiouAEIOU")
    has_vowel = False
    has_consonant = False

    for char in word:
        if char.isalnum():
            if char.isalpha():
                if char in vowels:
                    has_vowel = True
                else:
                    has_consonant = True
        else:
            # Character is not a digit or English letter
            return False

    return has_vowel and has_consonant
