import sys

def rotate(shape):
    """Rotates a list of (r, c) coordinates 90 degrees clockwise."""
    # (r, c) -> (c, -r)
    return [(c, -r) for r, c in shape]

def normalize(shape):
    """Translates shape so the top-leftmost square is at (0, 0) for comparison."""
    min_r = min(r for r, c in shape)
    min_c = min(c for r, c in shape)
    return sorted([(r - min_r, c - min_c) for r, c in shape])

def get_all_rotations(shape):
    """Returns the 4 distinct rotations of a polyomino."""
    rotations = []
    current = shape
    for _ in range(4):
        rotations.append(normalize(current))
        current = rotate(current)
    # Return only unique normalized rotations to avoid redundant checks
    unique = []
    for rot in rotations:
        if rot not in unique:
            unique.append(rot)
    return unique

def solve():
    # Read all lines from stdin
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    # Process the input into three polyominoes
    polyominoes_coords = []
    for i in range(3):
        coords = []
        for r in range(4):
            row_str = lines[i * 4 + r]
            for c in range(4):
                if row_str[c] == '#':
                    coords.append((r, c))
        polyominoes_coords.append(coords)

    # Pre-calculate all possible rotations for each piece
    all_variants = [get_all_rotations(p) for p in polyominoes_coords]

    # Total cells must be 16
    total_cells = sum(len(p) for p in polyominoes_coords)
    if total_cells != 16:
        print("No")
        return

    # Recursive backtracking to place polyominoes
    def can_place(grid, shape, dr, dc):
        for r, c in shape:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < 4 and 0 <= nc < 4) or grid[nr][nc]:
                return False
        return True

    def place(grid, shape, dr, dc, val):
        for r, c in shape:
            grid[r + dr][c + dc] = val

    grid = [[False for _ in range(4)] for _ in range(4)]

    def backtrack(piece_idx):
        if piece_idx == 3:
            # Check if all cells are filled
            return all(all(row) for row in grid)

        # Try all rotations of the current piece
        for variant in all_variants[piece_idx]:
            # Try all possible top-left positions in the 4x4 grid
            # Since shape is normalized to (0,0), we check all offsets
            for dr in range(-3, 4):
                for dc in range(-3, 4):
                    if can_place(grid, variant, dr, dc):
                        place(grid, variant, dr, dc, True)
                        if backtrack(piece_idx + 1):
                            return True
                        place(grid, variant, dr, dc, False)
        return False

    if backtrack(0):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
```

