import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Initialize distance matrix with infinity
    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = min(dist[u][v], w)
        idx += 3

    # Floyd-Warshall to find all-pairs shortest paths
    # Since there are no negative cycles, this is valid.
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][k] != INF and dist[k][j] != INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # DP state: dp[mask][last_node] = min weight to visit vertices in mask, ending at last_node.
    # Mask is a bitmask of visited vertices.
    dp = [[INF] * N for _ in range(1 << N)]

    # Base cases: start from any vertex i
    for i in range(N):
        dp[1 << i][i] = 0

    # Iterate through all masks (subsets of vertices)
    for mask in range(1, 1 << N):
        for u in range(N):
            if dp[mask][u] == INF:
                continue

            # Try moving to any vertex v not in the mask
            for v in range(N):
                if not (mask & (1 << v)):
                    if dist[u][v] != INF:
                        new_mask = mask | (1 << v)
                        new_weight = dp[mask][u] + dist[u][v]
                        if new_weight < dp[new_mask][v]:
                            dp[new_mask][v] = new_weight

    # The answer is the minimum weight in dp[(1 << N) - 1][i] for any i
    ans = INF
    final_mask = (1 << N) - 1
    for i in range(N):
        ans = min(ans, dp[final_mask][i])

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
```

