def smallestString(s: str) -> str:
    n = len(s)
    s_list = list(s)

    # Find the first character that is not 'a'
    start = -1
    for i in range(n):
        if s_list[i] != 'a':
            start = i
            break

    # If all characters are 'a', we must pick one character and change it to 'z'
    # To keep it lexicographically smallest, we change the last character.
    if start == -1:
        s_list[-1] = 'z'
        return "".join(s_list)

    # From the first non-'a' character, continue replacing characters 
    # with their previous alphabet letter until we hit an 'a' or the end of the string.
    for i in range(start, n):
        if s_list[i] == 'a':
            break
        # Convert char to previous alphabet character
        s_list[i] = chr(ord(s_list[i]) - 1)

    return "".join(s_list)
```

