from functools import lru_cache

def beautifulNumbers(low: int, high: int, k: int) -> int:
    def count_beautiful(n):
        s = str(n)
        length = len(s)

        @lru_cache(None)
        def dp(idx, diff, rem, is_less, is_started):
            # diff = count of even digits - count of odd digits
            if idx == length:
                return 1 if is_started and diff == 0 and rem == 0 else 0

            res = 0
            # Option to keep skipping leading zeros
            if not is_started:
                res += dp(idx + 1, diff, rem, True, False)

            limit = int(s[idx]) if not is_less else 9

            start = 1 if not is_started else 0
            for digit in range(start, limit + 1):
                new_is_less = is_less or (digit < limit)
                new_diff = diff + (1 if digit % 2 == 0 else -1)
                new_rem = (rem * 10 + digit) % k
                res += dp(idx + 1, new_diff, new_rem, new_is_less, True)

            return res

        return dp(0, 0, 0, False, False)

    # Use the property: count in [low, high] = count(high) - count(low - 1)
    # Since we use lru_cache, we must clear it or define it inside the scope
    return count_beautiful(high) - count_beautiful(low - 1)
```

