import sys

def solve():
    # Read H and W from the first line of input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    grid = [list(row) for row in input_data[2:]]

    # Keep track of which cookies are still present
    # present[i][j] is True if cookie (i, j) is still there
    present = [[True for _ in range(W)] for _ in range(H)]

    while True:
        marked = [[False for _ in range(W)] for _ in range(H)]
        changed = False

        # 1. Check rows
        for i in range(H):
            row_indices = [j for j in range(W) if present[i][j]]
            if len(row_indices) >= 2:
                first_color = grid[i][row_indices[0]]
                all_same = True
                for j in row_indices:
                    if grid[i][j] != first_color:
                        all_same = False
                        break
                if all_same:
                    for j in row_indices:
                        marked[i][j] = True
                        changed = True

        # 2. Check columns
        for j in range(W):
            col_indices = [i for i in range(H) if present[i][j]]
            if len(col_indices) >= 2:
                first_color = grid[col_indices[0]][j]
                all_same = True
                for i in col_indices:
                    if grid[i][j] != first_color:
                        all_same = False
                        break
                if all_same:
                    for i in col_indices:
                        marked[i][j] = True
                        changed = True

        # 3. Remove marked cookies
        if not changed:
            break

        for i in range(H):
            for j in range(W):
                if marked[i][j]:
                    present[i][j] = False

    # Count remaining cookies
    count = 0
    for i in range(H):
        for j in range(W):
            if present[i][j]:
                count += 1
    print(count)

if __name__ == "__main__":
    solve()
```

