import sys

def solve():
    # Read the 3x3 grid from stdin
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        A = [int(x) for x in input_data]
    except EOFError:
        return

    # Winning combinations for a 3x3 grid (indices 0-8)
    lines = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8), # Rows
        (0, 3, 6), (1, 4, 7), (2, 5, 8), # Cols
        (0, 4, 8), (2, 4, 6)            # Diagonals
    ]

    # memo dictionary for game states
    # state: (mask_red, mask_blue, turn_takahashi)
    memo = {}

    def check_winner(mask):
        for a, b, c in lines:
            if (mask & (1 << a)) and (mask & (1 << b)) and (mask & (1 << c)):
                return True
        return False

    def get_score(mask, A_vals):
        score = 0
        for i in range(9):
            if mask & (1 << i):
                score += A_vals[i]
        return score

    def play(mask_red, mask_blue, is_takahashi):
        state = (mask_red, mask_blue, is_takahashi)
        if state in memo:
            return memo[state]

        # Check if previous player won by completing a line
        if not is_takahashi: # Takahashi just moved
            if check_winner(mask_red):
                return 1 # Takahashi wins
        else: # Aoki just moved
            if check_winner(mask_blue):
                return -1 # Aoki wins

        # Check if board is full
        if (mask_red | mask_blue) == (1 << 9) - 1:
            score_t = get_score(mask_red, A)
            score_a = get_score(mask_blue, A)
            return 1 if score_t > score_a else -1

        # Try all available moves
        available_moves = [i for i in range(9) if not ((mask_red | mask_blue) & (1 << i))]

        if is_takahashi:
            # Takahashi wants to maximize result (1 > -1)
            best = -2
            for move in available_moves:
                res = play(mask_red | (1 << move), mask_blue, False)
                if res > best:
                    best = res
                if best == 1: break # Optimization
            memo[state] = best
            return best
        else:
            # Aoki wants to minimize result (-1 < 1)
            best = 2
            for move in available_moves:
                res = play(mask_red, mask_blue | (1 << move), True)
                if res < best:
                    best = res
                if best == -1: break # Optimization
            memo[state] = best
            return best

    # The game state space is small enough (3^9 states total) to be handled
    # However, we can solve it using a recursive minimax.
    result = play(0, 0, True)
    if result == 1:
        print("Takahashi")
    else:
        print("Aoki")

if __name__ == "__main__":
    solve()
```

