def findChampion(grid):
    n = len(grid)
    # A team is the champion if no other team is stronger than them.
    # Team b is stronger than team a if grid[b][a] == 1.
    # Therefore, team a is the champion if for all b, grid[b][a] == 0.
    for a in range(n):
