def longestCommonSufix(wordsContainer, wordsQuery):
    # A Trie stores strings. Since we need suffixes, we store strings in reverse.
    # Each node in the Trie will keep track of the "best" index based on the problem's criteria:
    # 1. Smallest length
    # 2. Smallest index (earliest occurrence)
    trie = {}

    # Helper function to determine if candidate 'idx' is better than 'current_best'
    def get_better_idx(idx, current_best):
        if current_best == -1:
            return idx

        len_idx = len(wordsContainer[idx])
        len_best = len(wordsContainer[current_best])

        if len_idx < len_best:
            return idx
        elif len_idx == len_best:
            return idx if idx < current_best else current_best
        return current_best

    # Build the Trie using reversed strings
    for i, word in enumerate(wordsContainer):
        node = trie
        # Reverse word to treat suffixes as prefixes
        for char in reversed(word):
            if char not in node:
                node[char] = {'_best': -1}
            node = node[char]
            node['_best'] = get_better_idx(i, node['_best'])

    # The root also needs a _best index for cases where no common suffix exists
    trie['_best'] = -1
    for i in range(len(wordsContainer)):
        trie['_best'] = get_better_idx(i, trie['_best'])

    ans = []
    for query in wordsQuery:
        node = trie
        best_idx = trie['_best']
        # Traverse the Trie with the reversed query
        for char in reversed(query):
            if char in node:
                node = node[char]
                best_idx = node['_best']
            else:
                break
        ans.append(best_idx)

    return ans
```

