def count_incremovable_subarrays(nums):
    n = len(nums)
    count = 0

    # Iterate through all possible subarrays [i, j)
    for i in range(n):
        for j in range(i + 1, n + 1):
            # Create the remaining array by removing the subarray from index i to j-1
            remaining = nums[:i] + nums[j:]

            # Check if the remaining array is strictly increasing
            is_strictly_increasing = True
            for k in range(len(remaining) - 1):
                if remaining[k] >= remaining[k + 1]:
                    is_strictly_increasing = False
                    break

            if is_strictly_increasing:
                count += 1

    return count
