        line1 = sys.stdin.readline().split()
        if not line1:
            return
        H, W, T = map(int, line1)
    except ValueError:
        return

    grid = [sys.stdin.readline().strip() for _ in range(H)]

    start_pos = None
    goal_pos = None
    candies = []

    for r in range(H):
        for c in range(W):
            char = grid[r][c]
            if char == 'S':
                start_pos = (r, c)
            elif char == 'G':
                goal_pos = (r, c)
            elif char == 'o':
                candies.append((r, c))

    # Total special nodes: Start, then candies, then Goal
    nodes = [start_pos] + candies + [goal_pos]
    num_candies = len(candies)
    num_nodes = len(nodes)

    # Distance matrix between all special nodes
    dist_matrix = [[float('inf')] * num_nodes for _ in range(num_nodes)]

    def bfs(start_idx):
        sr, sc = nodes[start_idx]
        dists = [[float('inf')] * W for _ in range(H)]
        dists[sr][sc] = 0
        queue = deque([(sr, sc)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == float('inf'):
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for i in range(num_nodes):
            tr, tc = nodes[i]
            dist_matrix[start_idx][i] = dists[tr][tc]

    for i in range(num_nodes):
        bfs(i)

    # DP state: dp[mask][last_node_index] = min distance to visit candies in mask and end at last_node
    # mask only includes candies (bits 0 to num_candies-1)
    # last_node_index is index in nodes list (0 to num_nodes-1)

    # To optimize, we only care about masks of candies visited.
    # dp[mask][i] where mask is bitmask of candies, i is index of the last visited candy (0..num_candies-1)
    # and start_pos is treated separately.

    dp = [[float('inf')] * num_candies for _ in range(1 << num_candies)]

    # Base case: Start to first candy
    for i in range(num_candies):
        dp[1 << i][i] = dist_matrix[0][i + 1]

    # Fill DP
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] == float('inf'):
                continue
            d = dp[mask][i]
            # Try moving to another candy
            for j in range(num_candies):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    new_dist = d + dist_matrix[i + 1][j + 1]
                    if new_dist < dp[new_mask][j]:
                        dp[new_mask][j] = new_dist

    # Check if goal is reachable without candies first
    ans = -1
    if dist_matrix[0][num_nodes - 1] <= T:
        ans = 0

    # Check combinations of candies then to goal
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] == float('inf'):
                continue

            # Total distance = distance to last candy + distance from last candy to goal
            total_dist = dp[mask][i] + dist_matrix[i + 1][num_nodes - 1]
            if total_dist <= T:
                # Count bits in mask
                count = bin(mask).count('1')
                if count > ans:
                    ans = count

    print(ans)

if __name__ == "__main__":
    solve()
