def punishmentNumber(n: int) -> int:
    def can_partition(s, target):
        # Base case: if we've reached the end of the string, check if target is 0
        if not s:
            return target == 0
        # If target becomes negative, this partition is invalid
        if target < 0:
            return False

        # Try all possible split points for the first substring
        for i in range(1, len(s) + 1):
            val = int(s[:i])
            if can_partition(s[i:], target - val):
                return True
        return False

    total_punishment = 0
    for i in range(1, n + 1):
        square_str = str(i * i)
        if can_partition(square_str, i):
            total_punishment += i * i

    return total_punishment
