def countSameColors(n, queries):
    nums = [0] * n
    answer = []
    current_count = 0

    for index, color in queries:
        old_color = nums[index]

        # If the color is already the same, no change in the count
        if old_color == color:
            answer.append(current_count)
            continue

        # Remove the contribution of the current element with its neighbors before updating
        # Check left neighbor
        if index > 0 and nums[index-1] != 0:
            if nums[index-1] == old_color:
                current_count -= 1
        # Check right neighbor
        if index < n - 1 and nums[index+1] != 0:
            if nums[index+1] == old_color:
                current_count -= 1

        # Update the color
        nums[index] = color

        # Add the contribution of the new color with its neighbors
        # Check left neighbor
        if index > 0 and nums[index-1] != 0:
            if nums[index-1] == color:
                current_count += 1
        # Check right neighbor
        if index < n - 1 and nums[index+1] != 0:
            if nums[index+1] == color:
                current_count += 1

        answer.append(current_count)

    return answer
