import heapq

def solve(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    # The problem can be modeled as a shortest path problem on a graph where nodes are characters 'a'-'z'
    # and edges are the transformations provided by original, changed, and cost.

    # 1. Initialize a 26x26 distance matrix with infinity
    inf = float('inf')
    dist = [[inf] * 26 for _ in range(26)]

    # The distance from a character to itself is 0
    for i in range(26):
        dist[i][i] = 0

    # 2. Populate initial edges from the given cost arrays
    for o, c, w in zip(original, changed, cost):
        u = ord(o) - ord('a')
        v = ord(c) - ord('a')
        if w < dist[u][v]:
            dist[u][v] = w

    # 3. Use the Floyd-Warshall algorithm to find all-pairs shortest paths
    # Since there are only 26 nodes, O(26^3) is very efficient.
    for k in range(26):
        for i in range(26):
            for j in range(26):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # 4. Calculate the total cost to convert source to target
    total_cost = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue

        u = ord(s_char) - ord('a')
        v = ord(t_char) - ord('a')

        if dist[u][v] == inf:
            return -1

        total_cost += dist[u][v]

    return total_cost
