def getMaxAlternatingSubarray(nums):
    max_len = -1
    n = len(nums)

    # Iterate through every possible starting position of a subarray
    for i in range(n - 1):
        # A subarray must start with s[1] = s[0] + 1
        if nums[i+1] == nums[i] + 1:
            current_len = 2
            # Check how far the alternating pattern continues
            for j in range(i + 2, n):
                # The required difference depends on whether the index is even or odd
                # Relative to the start i, the index j is (j - i)
                # If (j-i) is even, nums[j] should be nums[j-1] - 1
                # If (j-i) is odd, nums[j] should be nums[j-1] + 1
                if (j - i) % 2 == 0:
                    if nums[j] == nums[j-1] - 1:
                        current_len += 1
                    else:
                        break
                else:
                    if nums[j] == nums[j-1] + 1:
                        current_len += 1
                    else:
                        break
            max_len = max(max_len, current_len)

    return max_len
