def shortestBeautifulSubstring(s: str, k: int) -> str:
    n = len(s)
    min_len = float('inf')
    result = ""

    # Use a sliding window to find all substrings with exactly k ones
    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1

            if ones_count == k:
                current_len = j - i + 1
                current_substring = s[i:j+1]

                if current_len < min_len:
                    min_len = current_len
                    result = current_substring
                elif current_len == min_len:
                    if current_substring < result:
                        result = current_substring
                # Since we want the shortest and lexicographically smallest,
                # and adding more characters to the right will only increase length,
                # we can break the inner loop once we've exceeded k ones.
                # However, since we need exactly k, we can break as soon as we hit k+1.
                break 
        # Small optimization: if we found a 1 at index j, we only care about 
        # substrings starting at i. If s[i] is '0', a substring starting at i+1 
        # would be shorter and potentially lexicographically smaller.

    # To strictly adhere to the "shortest" then "lexicographically smallest" 
    # we need to be careful. Let's refine the search.

    best_substring = ""
    min_length = float('inf')

    for i in range(n):
        ones = 0
        for j in range(i, n):
            if s[j] == '1':
                ones += 1
            if ones == k:
                length = j - i + 1
                substring = s[i:j+1]
                if length < min_length:
                    min_length = length
                    best_substring = substring
                elif length == min_length:
                    if substring < best_substring:
                        best_substring = substring
                break # Found the shortest beautiful substring starting at i

    return best_substring
