import math

def canConnectAll(nums):
    """
    Determines if all indices in the nums array are connected via paths
    where an edge exists between indices i and j if gcd(nums[i], nums[j]) > 1.
    """
    n = len(nums)
    if n == 1:
        return True

    # Disjoint Set Union (DSU) to manage connected components
    parent = list(range(n))
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # Map each prime factor to the index of the first number encountered that has this factor
    # This avoids O(N^2) gcd checks by connecting numbers that share the same prime factor
    prime_to_index = {}

    for i in range(n):
        val = nums[i]
        if val == 1:
            # A number 1 cannot have gcd > 1 with any other number
            # Unless the array length is 1 (handled above)
            return False

        # Factorize val to find all its prime factors
        temp = val
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_index:
                    union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_index:
                union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

    # Check if all elements belong to the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
