    # Read the input string S from stdin
    S = sys.stdin.read().strip()
    if not S:
        return

    n = len(S)
    MOD = 998244353

    # A string is a valid parenthesis string if:
    # 1. The total count of '(' equals the total count of ')'
    # 2. At any point from left to right, the cumulative count of '(' 
    #    is greater than or equal to the cumulative count of ')'

    # If the length is odd, it can never be a valid parenthesis string
    if n % 2 != 0:
        print(0)
        return

    # dp[j] will store the number of ways to have a prefix with balance j
    # Balance is (count of '(') - (count of ')')
    dp = [0] * (n + 1)
    dp[0] = 1

    for char in S:
        new_dp = [0] * (n + 1)
        if char == '(':
            # Balance increases by 1
            for j in range(n):
                if dp[j]:
                    new_dp[j + 1] = dp[j]
        elif char == ')':
            # Balance decreases by 1, but cannot go below 0
            for j in range(1, n + 1):
                if dp[j]:
                    new_dp[j - 1] = dp[j]
        else: # char == '?'
            # Treat '?' as either '(' or ')'
            for j in range(n + 1):
                if dp[j]:
                    # Case '('
                    if j + 1 <= n:
                        new_dp[j + 1] = (new_dp[j + 1] + dp[j]) % MOD
                    # Case ')'
                    if j - 1 >= 0:
                        new_dp[j - 1] = (new_dp[j - 1] + dp[j]) % MOD
        dp = new_dp

    # The answer is the number of ways to end with a balance of 0
    print(dp[0])

