import sys
import itertools

def solve():
    # Read input
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        n = int(input_data[0])
        r_str = input_data[1]
        c_str = input_data[2]
    except EOFError:
        return

    # The constraints on N are very small (3 to 5).
    # We can use backtracking or exhaustive search.
    # A grid is defined by the positions of 'A', 'B', and 'C' in each row.
    # Each row must have exactly one A, one B, and one C.
    # Each column must have exactly one A, one B, and one C.

    # Possible row configurations: combinations of 3 positions out of N, 
    # and permutations of 'A', 'B', 'C' in those positions.
    possible_rows = []
    chars = ['A', 'B', 'C']
    for indices in itertools.combinations(range(n), 3):
        for p in itertools.permutations(chars):
            row = ['.'] * n
            for idx, char in zip(indices, p):
                row[idx] = char
            possible_rows.append("".join(row))

    grid = [[''] * n for _ in range(n)]

    # Column constraints trackers
    col_counts = [{'A': 0, 'B': 0, 'C': 0} for _ in range(n)]
    col_first_char = [None] * n

    def check_row_leftmost(row_idx, row_str):
        # Leftmost character in the i-th row must match R[i]
        for char in row_str:
            if char != '.':
                return char == r_str[row_idx]
        return False

    def solve_recursive(row_idx):
        if row_idx == n:
            # Final check: top-most character of each column must match C
            for j in range(n):
                if col_first_char[j] != c_str[j]:
                    return False
            return True

        for row_str in possible_rows:
            if not check_row_leftmost(row_idx, row_str):
                continue

            # Check if this row string violates column counts
            possible = True
            for j in range(n):
                char = row_str[j]
                if char != '.':
                    if col_counts[j][char] >= 1:
                        possible = False
                        break

            if not possible:
                continue

            # Check if this row string violates column leftmost condition
            # (If it's the first char in column j, it must match C[j])
            for j in range(n):
                char = row_str[j]
                if char != '.' and col_first_char[j] is None:
                    if char != c_str[j]:
                        possible = False
                        break

            if not possible:
                continue

            # Place row and recurse
            snapshot_first_chars = list(col_first_char)
            for j in range(n):
                char = row_str[j]
                if char != '.':
                    col_counts[j][char] += 1
                    if col_first_char[j] is None:
                        col_first_char[j] = char

            grid[row_idx] = row_str
            if solve_recursive(row_idx + 1):
                return True

            # Backtrack
            for j in range(n):
                char = row_str[j]
                if char != '.':
                    col_counts[j][char] -= 1
            for j in range(n):
                col_first_char[j] = snapshot_first_chars[j]

        return False

    if solve_recursive(0):
        print("Yes")
        for row in grid:
            print(row)
    else:
        print("No")

