import sys

def solve():
    # Read input from stdin
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        M = int(input_data[0])
        S = [input_data[1], input_data[2], input_data[3]]
    except EOFError:
        return

    # We want all reels to display the same digit 'd' (0-9)
    min_total_time = float('inf')
    possible = False

    for digit in "0123456789":
        # Find all positions of 'digit' in each string
        positions = []
        for i in range(3):
            pos = [j for j in range(M) if S[i][j] == digit]
            positions.append(pos)

        # If any string doesn't contain the digit, this digit is impossible
        if any(len(pos) == 0 for pos in positions):
            continue

        # Try all combinations of positions (t_0 mod M, t_1 mod M, t_2 mod M)
        # Since M is small (100), we can iterate through all combinations
        for p0 in positions[0]:
            for p1 in positions[1]:
                for p2 in positions[2]:
                    # We need to find the smallest t_max = max(t0, t1, t2)
                    # such that t_i mod M = p_i AND t_i are distinct.
                    # Let t_i = k_i * M + p_i
                    # We want to minimize max(k_0*M+p_0, k_1*M+p_1, k_2*M+p_2)
                    # subject to k_i >= 0 and t_i all distinct.

                    # There are only a few possibilities for k_i. 
                    # Since we have 3 reels, k_i will be 0, 1, or 2.
                    # We can iterate through all permutations of k values
                    # but the simplest is to test all k_i in {0, 1, 2}
                    for k0 in range(3):
                        for k1 in range(3):
                            for k2 in range(3):
                                t0 = k0 * M + p0
                                t1 = k1 * M + p1
                                t2 = k2 * M + p2
                                if t0 != t1 and t1 != t2 and t0 != t2:
                                    current_max = max(t0, t1, t2)
                                    if current_max < min_total_time:
                                        min_total_time = current_max
                                        possible = True

    if not possible:
        print("-1")
    else:
        print(min_total_time)

