import sys

MOD = 998244353

def solve():
    H, W = map(int, sys.stdin.readline().split())
    grid = [list(sys.stdin.readline().strip()) for _ in range(H)]

    # Directions: up, down, left, right
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    # Union-Find
    parent = {}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra
            return True
        return False

    # Assign ids to all cells
    idx = [[0]*W for _ in range(H)]
    cur = 0
    for i in range(H):
        for j in range(W):
            idx[i][j] = cur
            cur += 1

    # Initialize DSU for green cells
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                parent[idx[i][j]] = idx[i][j]

    # Union adjacent green cells
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                for di, dj in dirs:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                        union(idx[i][j], idx[ni][nj])

    # Count initial components
    comp_map = {}
    comp_count = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                r = find(idx[i][j])
                if r not in comp_map:
                    comp_map[r] = comp_count
                    comp_count += 1

    # For each red cell, compute change in components if turned green
    red_count = 0
    total_delta = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                red_count += 1
                seen = set()
                for di, dj in dirs:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                        r = find(idx[ni][nj])
                        seen.add(comp_map[r])
                # New cell merges seen components and adds 1 itself
                delta = 1 - len(seen)
                total_delta += delta

    # Expected value = comp_count + (sum delta) / red_count
    # We want (comp_count * red_count + total_delta) / red_count mod MOD
    P = (comp_count * red_count + total_delta) % MOD
    Q = red_count % MOD

    # Modular inverse of Q
    R = pow(Q, MOD-2, MOD)
    ans = (P * R) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
```

