        current_width = 0
        for length in L:
            if length > W:
                return False
            if current_width == 0:
                current_width = length
            else:
                if current_width + 1 + length <= W:
                    current_width += 1 + length
                else:
                    lines += 1
                    current_width = length
                    if lines > M:
