def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    bits = [0] * 31

    for num in nums:
        for b in range(31):
            if num & (1 << b):
                bits[b] += 1

    final_nums = [0] * len(nums)
    for b in range(31):
        for i in range(bits[b]):
            final_nums[i] |= (1 << b)

    final_nums.sort(reverse=True)

    result = 0
    for i in range(k):
        result = (result + final_nums[i] * final_nums[i]) % MOD

    return result
