def maxSum(nums: list[int], k: int) -> int:
    MOD = 10**9 + 7
    bit_counts = [0] * 31

    for num in nums:
        for b in range(31):
            if (num >> b) & 1:
                bit_counts[b] += 1

    ans = 0
    for _ in range(k):
        cur = 0
        for b in range(31):
            if bit_counts[b] > 0:
                cur |= 1 << b
                bit_counts[b] -= 1
        ans = (ans + cur * cur) % MOD

