import sys
from functools import lru_cache

def solve():
    input_data = sys.stdin.read().strip().split()
    N, H, W = map(int, input_data[:3])
    tiles = []
    idx = 3
    for _ in range(N):
        a, b = int(input_data[idx]), int(input_data[idx + 1])
        idx += 2
        tiles.append((a, b))

    full_mask = (1 << (H * W)) - 1

    @lru_cache(None)
    def dfs(mask, tile_index):
        if mask == full_mask:
            return True
        if tile_index == N:
            return False

        # Find first empty cell
        for pos in range(H * W):
            if not (mask >> pos) & 1:
                r, c = divmod(pos, W)
                break

        # Try placing current tile or skip it
        possible_states = []
        a, b = tiles[tile_index]
        for h, w in [(a, b), (b, a)]:
            if r + h <= H and c + w <= W:
                new_mask = mask
                valid = True
                for dr in range(h):
                    for dc in range(w):
                        bit = (r + dr) * W + (c + dc)
                        if (new_mask >> bit) & 1:
                            valid = False
                            break
                        new_mask |= (1 << bit)
                    if not valid:
                        break
                if valid:
                    possible_states.append(new_mask)

        # Option 1: skip this tile
        if dfs(mask, tile_index + 1):
            return True

        # Option 2: place it
        for new_mask in possible_states:
            if dfs(new_mask, tile_index + 1):
                return True
        return False

    result = dfs(0, 0)
    print("Yes" if result else "No")

