def canTraverseAllPairs(nums: list[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    if 1 in nums:
        return False

    max_val = max(nums)

    # Precompute smallest prime factors (SPF) for factorization
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # DSU (Disjoint Set Union)
    # We can connect indices to prime factors or directly between primes.
    # To keep it efficient, map each prime factor to the first index that has it,
    # and union the indices.
    parent = list(range(n))

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    prime_to_index = {}

    for i, num in enumerate(nums):
        temp = num
        while temp > 1:
            p = spf[temp]
            if p in prime_to_index:
                union(i, prime_to_index[p])
            else:
                prime_to_index[p] = i
            while temp % p == 0:
                temp //= p

    # Check if all indices are in the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
